ALTER TABLE "WorkspaceSettings" ADD COLUMN "policyThresholds" JSONB NOT NULL DEFAULT '{"routingConfidence":0.8,"engineering":0.7,"missingInfo":0.5,"multipleIssues":0.5,"matchProbability":0.9,"matchMargin":0.15}';
ALTER TABLE "WorkspaceSettings" ADD COLUMN "teamCriteria" JSONB NOT NULL DEFAULT '{"support":"General product usage or setup assistance","billing":"Invoices, charges or subscription administration","identity":"Authentication, permissions or sign-in failures","integrations":"Webhooks, external connectors or integration behaviour","platform":"Core service failures or platform availability","unknown":"Evidence is insufficient or no single team is appropriate"}';
UPDATE "WorkspaceSettings" SET "policyThresholds" = "policyThresholds" || jsonb_build_object('routingConfidence',"threshold");
